INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O peritônio é uma membrana serosa complexa que reveste a cavidade abdominal. Como se denomina a prega dupla de peritônio que conecta o estômago e a porção proximal do duodeno ao fígado?","options":{"a":"Omento maior.","b":"Omento menor.","c":"Mesentério.","d":"Mesocólon transverso.","e":"Ligamento falciforme."},"answer":"b","rationale":"O omento menor estende-se da curvatura menor do estômago e início do duodeno até a face visceral do fígado. É composto pelos ligamentos hepatogástrico e hepatoduodenal.","option_rationales":{"a":"Errada. Conecta a curvatura maior ao cólon transverso.","b":"Correta. Parte do sistema de fixação e trânsito vascular abdominal.","c":"Errada. Conecta o intestino delgado à parede posterior.","d":"Errada.","e":"Errada. Conecta o fígado à parede anterior."},"difficulty":"Fácil","tags":["Anatomia","Abdome","Esplanccnologia"]}', 'f7e7bd7a0db8b6d626cc7f13b10762f0', 200, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O fígado é dividido em lobos e segmentos. Qual estrutura divide o fígado em lobos anatômicos DIREITO e ESQUERDO na sua face DIAFRAGMÁTICA?","options":{"a":"Ligamento redondo.","b":"Fisura para o ligamento venoso.","c":"Ligamento falciforme.","d":"Veia cava inferior.","e":"Vesícula biliar."},"answer":"c","rationale":"O ligamento falciforme é uma prega peritoneal que fixa o fígado à parede anterior e o divide visivelmente em lobos direito e esquerdo superiormente.","option_rationales":{"a":"Errada. Resquício da veia umbilical, na borda livre do falciforme.","b":"Errada.","c":"Correta. Marco anatômico superficial hepático.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Abdome","Esplanccnologia"]}', 'df53a0d07bd30b9dba21a37b1e52ad2e', 201, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A irrigação arterial das vísceras abdominais deriva principalmente de três ramos ímpares da aorta abdominal. Qual desses ramos é responsável pelo suprimento do ''intestino médio'' (do duodeno distal ao terço distal do cólon transverso)?","options":{"a":"Tronco celíaco.","b":"Artéria mesentérica superior.","c":"Artéria mesentérica inferior.","d":"Artéria renal.","e":"Artéria ilíaca comum."},"answer":"b","rationale":"A artéria mesentérica superior supre as estruturas derivadas do intestino médio embrionário.","option_rationales":{"a":"Errada. Supre o intestino anterior (estômago, fígado, baço, pâncreas).","b":"Correta. Relação embriológica e vascular fundamental.","c":"Errada. Supre o intestino posterior (cólon distal e reto).","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Abdome","Vascularização"]}', 'd5b3839b53cf1b9971ea6bb55d1f461d', 202, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O pâncreas é um órgão retroperitoneal, exceto por uma pequena porção. Qual parte do pâncreas localiza-se dentro do ligamento esplenorrenal e pode ser lesada durante uma esplenectomia?","options":{"a":"Cabeça.","b":"Processo uncinado.","c":"Colo.","d":"Corpo.","e":"Cauda."},"answer":"e","rationale":"A cauda do pâncreas é a única porção relativamente móvel e que alcança o hilo do baço através do ligamento esplenorrenal.","option_rationales":{"a":"Errada. Fixa no C duodenal.","b":"Errada.","c":"Errada.","d":"Errada.","e":"Correta. Importância cirúrgica na preservação pancreática."},"difficulty":"Média","tags":["Anatomia","Abdome","Splatcnologia/Cirurgia"]}', 'b8ea6b8e3b2350358c15a0418ccd8b4c', 203, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ducto colédoco (biliar comum) une-se ao ducto pancreático principal para desembocar em qual estrutura na segunda porção do duodeno?","options":{"a":"Papila duodenal menor.","b":"Papila duodenal maior (Ampola de Vater).","c":"Óstio pilórico.","d":"Flexura duodenojejunal.","e":"Válvula ileocecal."},"answer":"b","rationale":"A ampola hepatopancreática (de Vater) desemboca na papila duodenal maior, marcando o fim do intestino anterior e início do médio.","option_rationales":{"a":"Errada. Recebe o ducto pancreático acessório.","b":"Correta. Via final de excreção biliar e pancreática.","c":"Errada.","d":"Errada. Ligamento de Treitz.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Abdome","Esplanccnologia"]}', '62960a4c88a682ee2e39975980b38713', 204, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Os rins são órgãos retroperitoneais protegidos por camadas de gordura e fáscia. Como se denomina a camada de tecido conjuntivo que envolve o rim e a glândula suprarrenal, separando-os da gordura pararrenal?","options":{"a":"Fáscia de Gerota (fáscia renal).","b":"Cápsula fibrosa.","c":"Gordura perirrenal.","d":"Peritônio parietal.","e":"Fáscia transversalis."},"answer":"a","rationale":"A fáscia renal (de Gerota) delimita o espaço perirrenal contendo o rim, a suprarrenal e a gordura perirrenal.","option_rationales":{"a":"Correta. Barreira anatômica importante para contenção de abscessos e hematomas renais.","b":"Errada. Adere diretamente à superfície do rim.","c":"Errada. Está interna à fáscia.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Abdome","Urologia"]}', '0a22a019b27d100c08e23126d8e11c0c', 205, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O estômago possui diversas regiões. Qual o nome da região que circunda a abertura do esôfago no estômago?","options":{"a":"Fundo.","b":"Corpo.","c":"Antro.","d":"Cárdia.","e":"Piloro."},"answer":"d","rationale":"A cárdia é a porção de entrada do estômago, situada ao nível da junção esofagogástrica.","option_rationales":{"a":"Errada. Parte superior em forma de cúpula.","b":"Errada. Maior parte do órgão.","c":"Errada. Parte distal dilatada.","d":"Correta. Termo derivado da proximidade com o coração (através do diafragma).","e":"Errada. Esfíncter de saída."},"difficulty":"Fácil","tags":["Anatomia","Abdome","Esplanccnologia"]}', '75d2003bf397eb72d6156a31202091a1', 206, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A veia porta do fígado é formada pela união de quais vasos principais, geralmente atrás do colo do pâncreas?","options":{"a":"Veia esplênica e veia mesentérica superior.","b":"Veia mesentérica superior e inferior.","c":"Veias hepáticas e veia cava inferior.","d":"Veia porta e veia renal.","e":"Veia esplênica e veia gástrica esquerda."},"answer":"a","rationale":"A veia porta recolhe sangue de todo o trato gastrointestinal abdominal. Forma-se pela junção da VMS e da veia esplênica (que costuma receber a VMI antes).","option_rationales":{"a":"Correta. Formação clássica do sistema porta.","b":"Errada.","c":"Errada. Veias hepáticas drenam para a VCI, saindo do fígado.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Abdome","Angiologia"]}', 'b735120dc7a54dc4a327a1c0e8c9f4d9', 207, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ducto cístico e o ducto hepático comum unem-se para formar qual estrutura?","options":{"a":"Ducto pancreático.","b":"Ducto biliar comum (Colédoco).","c":"Ducto parotídeo.","d":"Ducto torácico.","e":"Canal de Wirsung."},"answer":"b","rationale":"A árvore biliar começa nos fígados (hepáticos D e E), forma o hepático comum, recebe o cístico e torna-se colédoco.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia da via biliar extra-hepática.","c":"Errada.","d":"Errada.","e":"Errada. Nome alternativo do ducto pancreático principal."},"difficulty":"Fácil","tags":["Anatomia","Abdome","Esplanccnologia"]}', 'ac246de923626ea7d40e12f5b12a4edf', 208, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O intestino delgado é dividido em três partes principais. Qual sequência correta do trajeto do bolo alimentar após sair do estômago?","options":{"a":"Íleo, Jejuno, Duodeno.","b":"Duodeno, Jejuno, Íleo.","c":"Jejuno, Íleo, Duodeno.","d":"Duodeno, Íleo, Jejuno.","e":"Ceco, Jejuno, Íleo."},"answer":"b","rationale":"A ordem anatômica funcional é Duodeno (fixo/retroperitoneal), seguido pela porção móvel Jejuno e finalizando no Íleo.","option_rationales":{"a":"Errada.","b":"Correta. Sequência padrão do trato digestório.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Abdome","Esplanccnologia"]}', '5d4b0e13e31febf54a0ab16f3e652cfb', 209, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O estômago é irrigado por ramos do tronco celíaco. Qual artéria supre a CURVATURA MENOR do estômago e anastomosa-se com a artéria gástrica direita?","options":{"a":"Artéria gástrica esquerda.","b":"Artéria esplênica.","c":"Artéria gastromentoventrículo esquerda.","d":"Artéria hepática comum.","e":"Artéria gástrica curta."},"answer":"a","rationale":"A artéria gástrica esquerda (ramo do tronco celíaco) percorre a curvatura menor. A gástrica direita (ramo da hepática) completa a anastomose.","option_rationales":{"a":"Correta. Suprimento arterial principal gástrico.","b":"Errada.","c":"Errada. Supre a curvatura maior.","d":"Errada.","e":"Errada. Suprimem o fundo."},"difficulty":"Média","tags":["Anatomia","Abdome","Vascularização"]}', 'c87f729d2e7213128eea15ce07f128d8', 210, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O apêndice vermiforme localiza-se geralmente na base do ceco. Qual o nome do ponto de superfície, localizado no terço externo da linha entre o umbigo e a espinha ilíaca anterossuperior direita, onde a sensibilidade é máxima na apendicite aguda?","options":{"a":"Ponto de Murphy.","b":"Ponto de McBurney.","c":"Ponto de Blumberg.","d":"Ponto de Roux.","e":"Sinal do Psoas."},"answer":"b","rationale":"O ponto de McBurney corresponde à base do apêndice, onde este se origina do ceco, habitualmente na fossa ilíaca direita.","option_rationales":{"a":"Errada. Associado à colecistite.","b":"Correta. Marco clínico e propedêutico cirúrgico.","c":"Errada. É o sinal de descompressão dolorosa.","d":"Errada.","e":"Errada. É uma manobra física."},"difficulty":"Fácil","tags":["Anatomia","Abdome","Clínica/Superfície"]}', '87a990adb3c27f113cfc729f73a52be9', 211, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ducto torácico, maior vaso linfático do corpo, inicia-se no abdome em uma estrutura dilatada. Qual o nome dessa estrutura?","options":{"a":"Saco linfático cervical.","b":"Cisterna do quilo (Cisterna de Pecquet).","c":"Gânglio celíaco.","d":"Amígdala abdominal.","e":"Bursa omental."},"answer":"b","rationale":"A cisterna do quilo é o reservatório de linfa que recebe os troncos lombares e intestinais ao nível de L1-L2.","option_rationales":{"a":"Errada.","b":"Correta. Início do ducto torácico.","c":"Errada. Estrutura nervosa.","d":"Errada.","e":"Errada. Espaço peritoneal."},"difficulty":"Fácil","tags":["Anatomia","Abdome","Angiologia"]}', '89e17f1bf4bcf37408c1d405422ebe43', 212, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A veia renal esquerda tem um trajeto diferente da direita. Ela passa entre duas artérias principais antes de atingir a veia cava inferior. Quais são essas artérias?","options":{"a":"Aorta e Mesentérica Superior.","b":"Mesentérica Superior e Inferior.","c":"Tronco celíaco e Aorta.","d":"Renal direita e Esquerda.","e":"Aorta e Veia Cava."},"answer":"a","rationale":"O ''fenômeno de quebra-nozes'' ocorre quando a artéria mesentérica superior comprime a veia renal esquerda contra a aorta.","option_rationales":{"a":"Correta. Relação topográfica de pinçamento vascular renal.","b":"Errada.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Abdome","Angiologia/Topografia"]}', '840ae0e4c75544c86f1d1047c57c537f', 213, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''tríade portal'' é um conjunto de estruturas que viajam juntas dentro do ligamento hepatoduodenal. Quais são os três componentes da tríade portal?","options":{"a":"Veia Porta, Artéria Hepática Própria e Ducto Colédoco.","b":"Veia Hepática, Artéria Celíaca e Ducto Hepático.","c":"Veia Cava, Artéria Renal e Ureter.","d":"Veia Porta, Ducto Cístico e Artéria Gástrica.","e":"Veia Esplênica, Artéria Mesentérica e Ducto Pancreático."},"answer":"a","rationale":"A tríade portal é a unidade funcional de entrada/saída biliar do fígado no hilo hepático.","option_rationales":{"a":"Correta. Estruturas fundamentais do hilo hepático.","b":"Errada.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Abdome","Esplanccnologia"]}', 'ec9533fe45a149aa41c254d8b186ec3d', 214, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O pâncreas é um órgão de secreção mista. Qual região do pâncreas localiza-se POSTERIORMENTE aos vasos mesentéricos superiores (formando o ângulo aortomesentérico)?","options":{"a":"Cabeça.","b":"Processo uncinado.","c":"Colo.","d":"Corpo.","e":"Cauda."},"answer":"b","rationale":"O processo uncinado é uma projeção da cabeça do pâncreas que passa atrás da artéria e veia mesentéricas superiores.","option_rationales":{"a":"Errada.","b":"Correta. Detalhe da morfologia pancreática.","c":"Errada. Situa-se exatamente anterior aos vasos.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Abdome","Esplanccnologia"]}', '9d65bc777cc8c13ce65c35ea151cc49c', 215, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ureter possui três constrições anatômicas naturais ao longo do seu trajeto onde cálculos renais costumam impactar. Qual dessas NÃO é uma constrição habitual do ureter?","options":{"a":"Junção ureteropélvica (JUP).","b":"Cruzamento sobre as artérias ilíacas comuns.","c":"Passagem pela parede da bexiga urinária (Junção ureterovesical).","d":"Cruzamento pela artéria renal.","e":"Nenhuma das anteriores (todas são reais)."},"answer":"d","rationale":"O ureter inicia-se após a artéria renal, portanto não é comprimido por ela. As três áreas de estreitamento são a saída do rim, o cruzamento dos vasos ilíacos e a entrada na bexiga.","option_rationales":{"a":"Errada. É a primeira constrição.","b":"Errada. É a segunda constrição.","c":"Errada. É a terceira constrição.","d":"Correta. Não é um ponto de estreitamento anatômico pautado pela literatura.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Abdome","Urologia"]}', '34c8b6ad701f6fc24bbd70b05c1681a6', 216, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O baço é um órgão linfoide localizado no hipocôndrio esquerdo. Ele é protegido por quais costelas na sua face lateral?","options":{"a":"7ª à 9ª.","b":"9ª à 11ª.","c":"11ª e 12ª.","d":"5ª à 7ª.","e":"8ª e 10ª."},"answer":"b","rationale":"O baço situa-se sob o diafragma entre a 9ª e a 11ª costelas esquerdas. Fraturas nessas costelas aumentam o risco de ruptura esplênica.","option_rationales":{"a":"Errada.","b":"Correta. Marco topográfico protetor do baço.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Abdome","Topografia"]}', '831bc760f69db407a5b74fa3923440a5', 217, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''bolsa omental'' (pequeno saco) é um espaço peritoneal atrás do estômago. Como se comunica este espaço com a grande cavidade peritoneal?","options":{"a":"Através do forame omental (Forame de Winslow).","b":"Através do hiato esofágico.","c":"Através do óstio do cárdia.","d":"Através da ampola de Vater.","e":"Não há comunicação natural."},"answer":"a","rationale":"O forame omental (epiploico) é a única via de entrada natural para a bolsa omental, situada atrás do ligamento hepatoduodenal.","option_rationales":{"a":"Correta. Comunicação vital entre os sacos peritoneais.","b":"Errada.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Abdome","Topografia"]}', '8670d668dab4ea548e5f06a0adf3e462', 218, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O pavimentado pélvico e abdominal inferior é irrigado pelas artérias ilíacas. Qual dessas artérias é a principal fonte de suprimento para as vísceras pélvicas, região glútea e genitália externa?","options":{"a":"Artéria ilíaca externa.","b":"Artéria ilíaca interna.","c":"Artéria ilíaca comum.","d":"Artéria femoral.","e":"Artéria obturatória."},"answer":"b","rationale":"A ilíaca interna (hipogástrica) supre a pelve. A ilíaca externa supre o membro inferior (tornando-se femoral).","option_rationales":{"a":"Errada. Destinada ao membro inferior.","b":"Correta. Origem dos ramos viscerais e parietais pélvicos.","c":"Errada.","d":"Errada.","e":"Errada. É um ramo da interna."},"difficulty":"Fácil","tags":["Anatomia","Abdome/Pelve","Vascularização"]}', '23ca5df39a43fbb7b9f5a88a45a0db82', 219, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Ao nível de qual vértebra lombar a aorta abdominal geralmente bifurca-se nas artérias ilíacas comuns?","options":{"a":"L1.","b":"L2.","c":"L3.","d":"L4.","e":"L5."},"answer":"d","rationale":"A bifurcação da aorta ocorre na altura do corpo vertebral de L4, aproximadamente 2-3 cm abaixo da cicatriz umbilical.","option_rationales":{"a":"Errada. Origem do tronco celíaco.","b":"Errada. Origem da mesentérica superior.","c":"Errada. Origem da mesentérica inferior (aproximadamente).","d":"Correta. Marco topográfico fundamental para radiologia e cirurgia.","e":"Errada. Local de formação da veia cava inferior."},"difficulty":"Média","tags":["Anatomia","Abdome","Angiologia/Topografia"]}', 'f335311a1648a9684ba21fb8ffe82c90', 220, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ducto hepático comum recebe a drenagem de quais estruturas primárias?","options":{"a":"Fígado e Pâncreas.","b":"Ductos hepáticos direito e esquerdo.","c":"Ducto cístico e Vesícula.","d":"Colédoco e Papila.","e":"Apenas ducto lobar direito."},"answer":"b","rationale":"A união dos ductos hepáticos D e E forma o hepático comum.","option_rationales":{"a":"Errada.","b":"Correta. Início da via biliar extra-hepática propriamente dita.","c":"Errada.","d":"Errada. Está abaixo.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Abdome","Esplanccnologia"]}', '83eb46ba729c58d67e35c38efdeeb3c6', 221, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"As ''tênias do cólon'' são faixas longitudinais de músculo liso que percorrem o intestino grosso. Qual o papel dessas estruturas na fisiologia motora do cólon?","options":{"a":"Secretar muco.","b":"Aumentar a área de absorção.","c":"Sua contração encurta o intestino e forma as ''saculações'' ou ''haustras''.","d":"Funcionar como esfíncteres.","e":"Proteger contra bactérias."},"answer":"c","rationale":"Como as tênias são mais curtas que o comprimento total do cólon, elas puxam a parede do intestino, criando as bolsas características (haustras).","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Base anatômica da motilidade e aspecto do cólon.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Abdome","Esplanccnologia"]}', '7680a7d8f3c71a2767bd5140abacc8ee', 222, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ligamento de Treitz (músculo suspensor do duodeno) é um marco cirúrgico que define o limite entre quais porções do trato digestório?","options":{"a":"Esôfago e Estômago.","b":"Estômago e Duodeno.","c":"Duodeno e Jejuno.","d":"Íleo e Ceco.","e":"Intestino delgado e Intestino grosso."},"answer":"c","rationale":"O ligamento de Treitz fixa a flexura duodenojejunal. Clinicamente, marca o limite entre hemorragia digestiva alta (HDA) e baixa (HDB).","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Ponto anatômico de transição essencial.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Abdome","Esplanccnologia/Clínica"]}', '7ec4a4a3f29df349ea4b1e429136a740', 223, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"As glândulas suprarrenais (adrenais) localizam-se no polo superior dos rins. Qual é a principal diferença anatômica em termos de FORMA entre a glândula direita e a esquerda?","options":{"a":"A direita é piramidal e a esquerda é semilunar.","b":"A direita é semilunar e a esquerda é piramidal.","c":"Ambas são piramidais.","d":"Ambas são redondas.","e":"A esquerda é maior que a direita."},"answer":"a","rationale":"A glândula suprarrenal direita tem formato aproximado de pirâmide (ou chapéu de Napoleão), enquanto a esquerda é mais alongada e em forma de meia-lua (semilunar).","option_rationales":{"a":"Correta. Descrição morfológica clássica das adrenais.","b":"Errada.","c":"Errada.","d":"Errada.","e":"Errada. Geralmente a esquerda é um pouco maior, mas a questão foca na forma."},"difficulty":"Média","tags":["Anatomia","Abdome","Endocrinologia"]}', 'e0a0aa9e07cf8f2c68d1f1cd6f3d3e27', 224, 'draft');